739	        // partial sum-of-squares; loss_out (1 float) broadcasts clip_coef. The
740	        // reduced loss is already in *tok.loss_out (state), so this is free scratch.
741	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
742	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
743	        // Per-CTA contiguous element range over `grad` (the reduced grad, [total]).
744	        const int64_t total = kDecTotalElems;
745	        const int64_t base = total / nCTA, rem = total % nCTA;
746	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
747	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
