749	        float tsum = 0.0f;
750	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
751	            const float gv = grad[e0 + i];
752	            tsum += gv * gv;
753	        }
754	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
755	        float* red = sm.red;
756	        red[threadIdx.x] = tsum;
757	        __syncthreads();
758	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
759	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
760	            __syncthreads();
761	        }
762	        if (threadIdx.x == 0) sq_part[cta] = red[0];
