770	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
771	                coef = st.grad_clip / (total_norm + 1e-6f);
772	            *coef_bc = coef;
773	        }
774	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
775	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
