778	    // ── P2.6 (PRODIGY ONLY): STAGED cross-ALL-tensors d-estimate. The apply tail
779	    //    (apply_optimizer<Prodigy>) reads st.d_factor (the effective LR scale d),
780	    //    a GLOBAL reduction over EVERY element of EVERY tensor. We compute it here,
781	    //    BYTE-FAITHFUL to the live eager multi-tensor path (prodigy_sm90.cuh:465-
782	    //    544, the order prodigy.py → _ops.prodigy_fused_step actually executes):
783	    //      d_prev  = persisted d_lr  (step 1: d0 cold-start — the zero-init state
784	    //                slot would give d_prev=0 ⇒ d=0 ⇒ frozen params; eager inits
785	    //                _d_lr=d0=1e-6, so seed it here, the grokfast-style step-1 fix)
786	    //      r_ema  <- beta3·r_ema + Σ d_prev²·<g, p0−p>     (decay persisted SCALAR,
787	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
788	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
789	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
790	    //
791	    //    DETERMINISM — FIXED-PARTITION reduction (mirrors the A/A/A-CLEAN GrokAdamW
792	    //    P2.5 grad-norm reduce above), NOT the work-steal task-queue drain. WHY THIS
793	    //    SHAPE: the previous form drained the global TaskQueue (q.next_block →
794	    //    atomicAdd(g_next_task)) inside phaseA and reset that SAME counter in a
795	    //    sync_RESET barrier (B2.6a). The work-steal claim order is timing-dependent,
796	    //    so each CTA's (r,s) slot holds a potentially DIFFERENT tensor subset run-to-
797	    //    run; because fp32 add is non-associative, the per-CTA partials then regroup
798	    //    the same values differently and the owner's d can differ at ULP level from
799	    //    step>=2 (a COMPONENT_CONTRACT deterministic-reduction violation — even where
800	    //    it happens to be empirically bit-exact on a given GPU/workload, it is not
801	    //    deterministic BY CONSTRUCTION). GrokAdamW's P2.5 reduces a FIXED contiguous
802	    //    element range per CTA with a plain sync() and is A/A/A-CLEAN; prodigy now
803	    //    uses the IDENTICAL shape — deterministic by construction, independent of CTA
804	    //    timing. Each CTA owns [e0,e0+ecnt) of the FLAT [0,total) arrays —
805	    //    params/param_init/grad are parallel flat blobs, so a contiguous flat range
806	    //    sum == the cross-all-TENSORS sum (tensor boundaries are irrelevant to a
807	    //    global Σ). The per-element contribution still CALLS the canonical
808	    //    prodigy_partials_step (prodigy.h:28-53, single-source). NO float atomic;
809	    //    per-CTA (r,s) slot publish → ONE plain grid barrier → CTA0 owner-sums
810	    //    ascending → EMA-decay/update_d → broadcast → ONE plain grid barrier.
811	    //    g_next_task is UNTOUCHED here (B2 already reset it to 0), so P3's queue
812	    //    drain runs unchanged — no sync_reset needed in P2.6.
813	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
814	    if constexpr (Opt == OptId::Prodigy) {
815	        // Per-CTA (r,s) slots in opt_reduce ([r slots | s slots]) + the reduced-d
816	        // broadcast slot. d_prev: persisted d_lr (slot 2), or d0 cold-start at step 1.
817	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
818	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
819	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
820	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
821	        // FIXED contiguous element range over the flat [0,total_p) arrays (same split
822	        // as GrokAdamW P2.5: even base + remainder to the low CTAs → deterministic).
823	        const int64_t total_p = kDecTotalElems;
824	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
825	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
826	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
827	        float r_acc = 0.0f, s_acc = 0.0f;
828	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
829	            // Canonical per-element partials (prodigy.h:28-53): r carries d²·<g,p0−p>,
830	            // s carries d²·|g| (the L1-norm denominator). params/param_init/grad are
831	            // flat blobs → index pe0+i is the same element in all three.
832	            algo::prodigy_partials_step(params, st.param_init, grad,
833	                                        d_prev, pe0 + i, r_acc, s_acc);
834	        }
835	        // Deterministic in-CTA two-value reduction (fixed thread count) → thread0
836	        // publishes this CTA's (r,s) slot. No atomic.
837	        float r_block, s_block;
838	        prim::block_reduce_sum2_f32(r_acc, s_acc, r_block, s_block);
839	        if (threadIdx.x == 0) { r_part[cta] = r_block; s_part[cta] = s_block; }
840	        bar.sync();   // B2.6a: all per-CTA (r,s) partials published & visible
841	        // Owner block (CTA0 thread0): ascending owner-sum + EMA decay + accumulate +
842	        // d_coef + update_d, byte-matching launch_multi_tensor_prodigy_fused_reduce_step.
843	        if (cta == 0 && threadIdx.x == 0) {
844	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
845	            for (int c = 0; c < nCTA; ++c) { r_step += r_part[c]; s_step += s_part[c]; }
846	            // Decay persisted scalars by beta3, then add this step's reduction.
847	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
848	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
849	            // d = max(d_prev, d_coef·r_ema/|s_ema|). prodigy_update_d does
850	            // max(d_prev, r/|s|) verbatim, so fold d_coef into the numerator copy
851	            // (persisted r_ema stays UNSCALED — returned/persisted, eager parity).
852	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
853	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
854	            st.prodigy_persist[1] = s_ema;
855	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
856	            d_bc[0]               = d_new;          // broadcast to all CTAs
857	        }
858	        bar.sync();   // B2.6b: d visible to every CTA before the apply
859	        st.d_factor = d_bc[0];                      // the reduced d the tail reads
860	    }
