1101	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
1102	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas),
1103	// so any cap is hang-safe as long as the workspace + dW-tile/embedding ownership
1104	// use the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
1105	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
1106	// scratch fits (the scratch is nCTA×slab). Determinism is preserved per fixed
1107	// nCTA (the dW/embedding owner maps are functions of nCTA).
1108	template <OptId Opt>
1109	cudaError_t launch_fused_decoder_megakernel_tc(
1110	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
1111	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
1112	        int ncta_cap = 0) {
1113	    int dev = 0;
1114	    cudaError_t err = cudaGetDevice(&dev);
1115	    if (err != cudaSuccess) return err;
1116	    int n_sms = 0;
1117	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1118	    if (err != cudaSuccess) return err;
1119	
1120	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
1121	    // (0 here — DecTcSmem is static). If the static smem + 200-reg consumer
1122	    // can't place one block/SM, REFUSE (the grid barrier would hang).
1123	    int occ = 0;
1124	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1125	        &occ, (const void*)&fused_decoder_megakernel_tc<Opt>, SG_TC_MEGA_BLOCK,
1126	        /*dynamicSMemBytes=*/0);
1127	    if (err != cudaSuccess) return err;
1128	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1129	
1130	    unsigned launch_ctas = (unsigned)n_sms;
1131	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
1132	    ctx.n_ctas = launch_ctas;
1133	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms,
1134	    // AND it guarantees full token tiles for the projections). NO G-divisibility
1135	    // guard: the split-K dW uses a FLOOR-BALANCED K-partition (dectc_dw_run_tile_
1136	    // splitk) that sums to KS exactly for any KS≥G, so it works at the production
1137	    // truncated B (e.g. 4176, where head KS=B/16=261 is NOT divisible by G=4).
1138	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
1139	
1140	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1141	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1142	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1143	
1144	    dim3 grid(launch_ctas), block(SG_TC_MEGA_BLOCK);
1145	    fused_decoder_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
1146	        ctx, params, tok, grad, lr, step, st);
1147	    return cudaGetLastError();
1148	}
