52	// Effective nCTA the launcher will use (must match for workspace + ownership).
53	static int tc_effective_nctas(const torch::Tensor& params, int ncta_cap) {
54	    int dev = params.get_device();
55	    int n_sms = 1;
56	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
57	    int n = n_sms;
58	    if (ncta_cap > 0 && ncta_cap < n) n = ncta_cap;
59	    return n;
60	}
