365	// ── TC workspace layout (carved from tok.workspace; the host sizes it for the
366	//    TC path — see dec_tc_workspace_floats). Regions (float units):
367	//      [0 .. acts_f)                      : DecActs bf16 region (reinterpreted)
368	//      [acts_f .. acts_f + nCTA*scratch)  : per-CTA tile scratch (f32)
369	//      [.. + nCTA*kLnVecElems)            : per-CTA LN-vec partials (f32)
370	//      [.. + nCTA)                        : per-CTA loss slots (f32)
371	//      [.. + 1)                           : reduced scalar loss (host reads it)
372	//    acts_f = ceil(acts_bf16 / 2). ──
373	__host__ __device__ __forceinline__ int64_t dec_tc_acts_floats(int T, int B) {
374	    // mirror dectc::dec_acts_bind's running offset (bf16 elems) → floats.
375	    const int64_t d = dec::kD, dff = dec::kDff, V = dec::kVocab, L = dec::kLayers;
376	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
377	    int64_t bf = 0;
378	    for (int li = 0; li < L; ++li) bf += Td + Td + Td + Tff + T3d + Td + Tff + Td;
379	    bf += (int64_t)B * d + (int64_t)B * V + Td;     // X_hn + dY_logits + dh0
380	    return (bf + 1) / 2;
381	}
382	// dW split-K partial floats (0 when G==1 → no extra scratch, single-CTA path).
383	__host__ __device__ __forceinline__ int64_t dec_tc_dw_part_floats() {
384	    return (dectc::kDecDwSplitK > 1) ? dectc::dec_dw_part_floats(dectc::kDecDwSplitK) : 0;
385	}
386	// STAGED-optimizer cross-CTA reduction scratch (Prodigy d-estimate). The Prodigy
387	// stage publishes per-CTA (r,s) slots (2*nCTA) + a reduced-d slot (1) — an owner-
388	// computes tree (opt_stages_precompute.cuh), NO float atomic. Sized for the
389	// LARGEST nCTA (one CTA/SM = #SMs); tiny (≤ 2*132+1 ≈ 1 KB) and carved
390	// UNCONDITIONALLY so the opt-agnostic host launcher (dec_tc_launcher_scratch)
391	// allocates one workspace that fits every OptId. Unused by AdamW/Lion/… (their
392	// P3 never touches this region), so adding it leaves those cells byte-identical.
393	__host__ __device__ __forceinline__ int64_t dec_tc_opt_reduce_floats(int nCTA) {
394	    return (int64_t)2 * nCTA + 1;            // [r slots | s slots | reduced d]
395	}
396	// ── Muon (STAGED grid-cooperative Newton-Schulz) per-matrix scratch. IDENTICAL in
397	//    shape to the vit twin (vit_tc_muon_floats): the NS chain runs ONE 2D weight at
398	//    a time over all CTAs; the scratch holds X/A/AX/AAX/orth for the LARGEST 2D weight
399	//    + the per-CTA Frobenius-norm partials + inv_norm. The momentum buffer (muon_buf)
400	//    is NOT here — it PERSISTS across steps as optimizer state, bound to the m slice
401	//    (st.exp_avg). Largest decoder 2D weight: ff.0/ff.2 = 512×128 = 65536 numel; largest
402	//    rows = 512 ⇒ A = 512×512 (dectc::kDecMuonMaxNumel/kDecMuonMaxRows). Carved
403	//    UNCONDITIONALLY (≈ 4·65536 + 512² + nCTA + 1 floats ≈ 2 MB) so the opt-agnostic
404	//    launcher (dec_tc_launcher_scratch) fits every OptId; unused by every non-Muon cell
405	//    (its P2.7/P3-2D branches are if-constexpr'd out → byte-identical). ──
406	__host__ __device__ __forceinline__ int64_t dec_tc_muon_floats(int nCTA) {
407	    // X + AX + AAX + orth (each maxNumel) + A (maxRows²) + nrm_partials(nCTA) + inv_norm(1)
408	    return (int64_t)4 * dectc::kDecMuonMaxNumel
409	         + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows
410	         + nCTA + 1;
411	}
412	// ── LookSAM (STAGED in-kernel SAM 2nd backward) transient scratch. The SAM step
413	//    perturbs p in place, runs a SECOND fwd+bwd at p', and needs (a) a param BACKUP
414	//    for the exact restore (eager clones p before perturbing) + (b) a SEPARATE g_sam
415	//    grad buffer so the 2nd backward does NOT clobber the first grad `grad` (sam_dir
416	//    = g_sam − grad reads both). Both are total-sized + transient (NOT persistent
417	//    state — sam_dir itself persists in the `extra` state slice, bound by the cell).
418	//    Carved UNCONDITIONALLY (≈ 2·422755 ≈ 3.4 MB) so the opt-agnostic launcher fits
419	//    every OptId; unused by every non-LookSAM cell (its phase is if-constexpr'd out
420	//    → byte-identical). nrm_partials(nCTA)+inv_norm(1) for the ‖g‖ reduction reuse
421	//    the loss workspace (sq_part/coef_bc, as GrokAdamW's P2.5 does), so no extra here. ──
422	__host__ __device__ __forceinline__ int64_t dec_tc_looksam_floats() {
423	    return (int64_t)2 * kDecTotalElems;       // [sam_backup | sam_grad]
424	}
425	// ── SuperGrok2 compile-time dims = the race config (== SG2Dims defaults). The
426	//    composed megakernel reads weights from HBM, so the only SG2 workspace is the
427	//    per-CTA meta-net scratch (sg2_ws_stride, sized for the LARGEST tensor — the
428	//    65536-element ff weights — which bounds every tensor's intermediates + the
429	//    in-kernel segmented-sort key/idx/perm/unsort). ──
430	using DecSG2Dims = SG2Dims<>;
431	constexpr int kDecSG2Nmax = 65536;   // max(kDecSizes) — the per-CTA carve upper bound
432	// Per-CTA SG2 slice = row_off64 staging (kDecNumTensors int64 = 2*N floats) + the
433	// meta-net scratch (sized for the largest tensor). The row_off64 prefix lets the
434	// SG2State.row_off (const int64_t*) be built on-device from the __constant__ int
435	// kDecOffsets (the adapter for the int-typed layout tables).
436	__host__ __device__ __forceinline__ int64_t dec_sg2_ws_stride_floats() {
437	    return (int64_t)2 * kDecNumTensors
438	         + sg2_ws_stride<DecSG2Dims>((int64_t)kDecSG2Nmax);
439	}
440	__host__ __device__ __forceinline__ int64_t dec_tc_sg2_floats(int nCTA) {
441	    // +1 for the 8-byte realignment slack of sg2_ws_base (the per-CTA slice fronts an
442	    // int64 row_off64 array; kDecTotalElems is odd, so the base may need a +1 bump).
443	    return (int64_t)nCTA * dec_sg2_ws_stride_floats() + 1;
444	}
445	__host__ __device__ __forceinline__ int64_t dec_tc_workspace_floats(int T, int B, int nCTA) {
446	    return dec_tc_acts_floats(T, B)
447	         + (int64_t)nCTA * dectc::dec_tile_scratch_total_f32()
448	         + (int64_t)nCTA * dectc::kLnVecElems
449	         + nCTA + 1
450	         + dec_tc_dw_part_floats()            // split-K dW partials (G>1)
451	         + dec_tc_opt_reduce_floats(nCTA)     // STAGED-opt (Prodigy) reduce slots
