453	         + dec_tc_looksam_floats()            // STAGED-opt (LookSAM) SAM 2nd-bwd scratch
454	         + dec_tc_sg2_floats(nCTA);           // SuperGrok2 meta-net per-CTA scratch (carve-LAST)
